import inspect
import asyncio
from functools import wraps, partial
from typing import Any, Callable

def iscoroutinefunction(func):
    return asyncio.iscoroutinefunction(func)

def check_callable_chain(callable_obj, check_func):
    curr = callable_obj
    while True:
        if check_func(curr):
            return True
        dunder_call = getattr(curr, "__call__", None)
        if dunder_call and check_func(dunder_call):
            return True
        if isinstance(curr, partial):
            curr = curr.func
        elif hasattr(curr, "__wrapped__"):
            curr = curr.__wrapped__
        else:
            break
    return False

class Wrapper:
    def __init__(self, wrapped):
        self.__wrapped__ = wrapped
    async def __call__(self):
        return await self.__wrapped__()

class Wrapped:
    def __call__(self):
        return "hello"

w = Wrapper(Wrapped())
print(f"Callable instance wrapper: {check_callable_chain(w, iscoroutinefunction)}") # Expected: True
